mapper.update:
UPDATE tb_purchase_order_dt
SET receipt_close_at = #{receiptCloseAt},
    updated_by = #{updatedBy},
    updated_at = now()
WHERE purchase_order_detail_id = #{purchaseOrderDetailId, jdbcType=BIGINT}
  AND purchase_order_id = #{purchaseOrderId, jdbcType=BIGINT}
  AND tenant_id = #{tenantId, jdbcType=BIGINT}
  AND receipt_close_at <> #{receiptCloseAt}

mapper.delete:
DELETE FROM tb_purchase_order_dt
WHERE purchase_order_detail_id = #{purchaseOrderDetailId, jdbcType=BIGINT}
  AND purchase_order_id = #{purchaseOrderId, jdbcType=BIGINT}
  AND tenant_id = #{tenantId, jdbcType=BIGINT}

DELETE FROM tb_purchase_request_dt
WHERE purchase_request_detail_id = #{purchaseRequestDetailId, jdbcType=BIGINT}
  AND tenant_id = #{tenantId, jdbcType=BIGINT}
